(function(){
  function C(n){ try { return Java.loadClass(n); } catch (e) { return Packages.java.lang.Class.forName(n); } }
  if (typeof AutoJS === 'undefined') { throw new Error('端点: server 侧 AutoJS 全局缺失（通道未注入）'); }
  var ps = AutoJS.players();
  if (ps === null || ps.length < 1) { throw new Error('端点: 世界内没有玩家'); }
  var p = ps[0];
  var before = String(p.containerMenu.getClass().getSimpleName());
  var Op = C('com.merlinkitsune.astral_dice.shop.CardShopOpener');
  Op.open(p);
  var after = String(p.containerMenu.getClass().getSimpleName());
  return { beforeMenu: before, afterMenu: after, opened: after === 'CardShopMenu' };
})()
